def longest_common_subpath(n, paths):
    def contains_subarray(path, candidate):
        for i in range(len(path) - len(candidate) + 1):
            if path[i:i + len(candidate)] == candidate:                # direct element by element comparison
                return True
        return False

    best = 0
    first = paths[0]
    for i in range(len(first)):
        for j in range(i, len(first)):
            candidate = first[i:j + 1]
            if all(contains_subarray(path, candidate) for path in paths[1:]):
                best = max(best, len(candidate))
    return best


if __name__ == "__main__":
    n = 5
    paths = [[1, 2, 3, 4], [2, 3, 4, 5], [0, 2, 3, 9]]
    print(longest_common_subpath(n, paths))

