import java.util.*;

public class Main {
    int longestCommonSubpath(int n, int[][] paths) {
        int best = 0;
        int[] first = paths[0];
        for (int i = 0; i < first.length; i++) {
            for (int j = i; j < first.length; j++) {
                int[] candidate = Arrays.copyOfRange(first, i, j + 1);
                boolean inAll = true;
                for (int p = 1; p < paths.length; p++) {
                    if (!containsSubarray(paths[p], candidate)) { inAll = false; break; }
                }
                if (inAll) best = Math.max(best, candidate.length);
            }
        }
        return best;
    }

    boolean containsSubarray(int[] path, int[] candidate) {
        for (int i = 0; i <= path.length - candidate.length; i++) {
            boolean match = true;
            for (int k = 0; k < candidate.length; k++) {                     // direct element by element comparison
                if (path[i + k] != candidate[k]) { match = false; break; }
            }
            if (match) return true;
        }
        return false;
    }

    public static void main(String[] args) {
        int n = 5;
        int[][] paths = {{1, 2, 3, 4}, {2, 3, 4, 5}, {0, 2, 3, 9}};
        Main solution = new Main();
        System.out.println(solution.longestCommonSubpath(n, paths));
    }
}

