def longest_common_subpath(n, paths):
    base, mod = 131, (1 << 61) - 1

    def window_hashes(path, length):
        hashes = set()
        power = pow(base, length - 1, mod)
        h = 0
        for i in range(length):
            h = (h * base + path[i]) % mod
        hashes.add(h)
        for i in range(length, len(path)):
            h = (h - path[i - length] * power) % mod
            h = (h * base + path[i]) % mod                              # roll the window forward by one position
            hashes.add(h % mod)
        return hashes

    def feasible(length):
        if length == 0:
            return True
        common = window_hashes(paths[0], length)
        for path in paths[1:]:
            if len(path) < length:
                return False
            common &= window_hashes(path, length)                        # keep only hashes seen in every path so far
            if not common:
                return False
        return True

    lo, hi = 0, min(len(p) for p in paths)
    answer = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        if feasible(mid):
            answer = mid
            lo = mid + 1                                                   # a longer common subpath might still exist
        else:
            hi = mid - 1                                                     # too long, search a shorter range instead
    return answer


if __name__ == "__main__":
    n = 5
    paths = [[1, 2, 3, 4], [2, 3, 4, 5], [0, 2, 3, 9]]
    print(longest_common_subpath(n, paths))

