import java.util.*;

public class Main {
    int longestCommonSubpath(int n, int[][] paths) {
        long base = 131, mod = (1L << 61) - 1;
        int lo = 0, hi = Integer.MAX_VALUE;
        for (int[] p : paths) hi = Math.min(hi, p.length);
        int answer = 0;
        while (lo <= hi) {
            int mid = (lo + hi) / 2;
            if (feasible(paths, mid, base, mod)) {
                answer = mid;
                lo = mid + 1;                                                     // a longer common subpath might still exist
            } else {
                hi = mid - 1;                                                       // too long, search a shorter range instead
            }
        }
        return answer;
    }

    boolean feasible(int[][] paths, int length, long base, long mod) {
        if (length == 0) return true;
        Set<Long> common = windowHashes(paths[0], length, base, mod);
        for (int p = 1; p < paths.length; p++) {
            if (paths[p].length < length) return false;
            common.retainAll(windowHashes(paths[p], length, base, mod));           // keep only hashes seen in every path
            if (common.isEmpty()) return false;
        }
        return true;
    }

    Set<Long> windowHashes(int[] path, int length, long base, long mod) {
        Set<Long> hashes = new HashSet<>();
        long power = 1;
        for (int i = 0; i < length - 1; i++) power = (power * base) % mod;
        long h = 0;
        for (int i = 0; i < length; i++) h = (h * base + path[i]) % mod;
        hashes.add(h);
        for (int i = length; i < path.length; i++) {
            h = ((h - path[i - length] * power % mod) % mod + mod) % mod;
            h = (h * base + path[i]) % mod;                                          // roll the window forward
            hashes.add(h);
        }
        return hashes;
    }

    public static void main(String[] args) {
        int n = 5;
        int[][] paths = {{1, 2, 3, 4}, {2, 3, 4, 5}, {0, 2, 3, 9}};
        Main solution = new Main();
        System.out.println(solution.longestCommonSubpath(n, paths));
    }
}

