#include <bits/stdc++.h>
using namespace std;

unordered_set<long long> windowHashes(vector<int>& path, int length, long long base, long long mod) {
    unordered_set<long long> hashes;
    long long power = 1;
    for (int i = 0; i < length - 1; i++) power = (power * base) % mod;
    long long h = 0;
    for (int i = 0; i < length; i++) h = (h * base + path[i]) % mod;
    hashes.insert(h);
    for (int i = length; i < (int)path.size(); i++) {
        h = ((h - (long long)path[i - length] * power % mod) % mod + mod) % mod;
        h = (h * base + path[i]) % mod;                                            // roll the window forward
        hashes.insert(h);
    }
    return hashes;
}

bool feasible(vector<vector<int>>& paths, int length, long long base, long long mod) {
    if (length == 0) return true;
    unordered_set<long long> common = windowHashes(paths[0], length, base, mod);
    for (int p = 1; p < (int)paths.size(); p++) {
        if ((int)paths[p].size() < length) return false;
        unordered_set<long long> pathHashes = windowHashes(paths[p], length, base, mod);
        unordered_set<long long> intersected;
        for (long long h : common) {
            if (pathHashes.count(h)) intersected.insert(h);                          // keep only shared hashes
        }
        common = intersected;
        if (common.empty()) return false;
    }
    return true;
}

int longestCommonSubpath(int n, vector<vector<int>>& paths) {
    long long base = 131, mod = (1LL << 61) - 1;
    int lo = 0, hi = INT_MAX;
    for (auto& p : paths) hi = min(hi, (int)p.size());
    int answer = 0;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        if (feasible(paths, mid, base, mod)) {
            answer = mid;
            lo = mid + 1;                                                            // a longer subpath might still exist
        } else {
            hi = mid - 1;                                                              // too long, search shorter lengths
        }
    }
    return answer;
}

int main() {
    int n = 5;
    vector<vector<int>> paths = {{1, 2, 3, 4}, {2, 3, 4, 5}, {0, 2, 3, 9}};
    cout << longestCommonSubpath(n, paths) << endl;
    return 0;
}
